ORIGINAL_HASHES = json.loads('{"ragstudy/core.py": "340bb505c909d60698574c51e949101450f47a7a69173c7ed6cb74c2203854b8", "ragstudy/api.py": "35fab9d1862434a549aecde94d6b2ef7c2ad9cf6c21b1f2bd3a38574d173537d", "ragstudy/evaluation.py": "152d38cb9221f8aa08fdeda4a2a209a73a6af9a56e8a21caf8b33795d6c4accb", "tests/test_study.py": "3405930282f733e2013a08d07be026e24a148724c8d8b27610fe6a9b468a724a"}')


def atomic_write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + ".atomic_fix_tmp")
    temp.write_bytes(data)
    temp.replace(path)


def install(root):
    root = Path(root)
    if not (root/"experiment.py").is_file() or not (root/"ragstudy/http_transport.py").is_file():
        raise ValueError("Put apply_atomic_fix.py beside experiment.py in the existing curl/sentence-fixed project.")
    for name, source in PATCH_FILES.items():
        if name.endswith(".py"):
            ast.parse(source, filename=name)
        path = root/name
        if path.exists():
            current = hashlib.sha256(path.read_bytes()).hexdigest()
            new = hashlib.sha256(source.encode("utf-8")).hexdigest()
            if current not in (ORIGINAL_HASHES.get(name), new):
                raise ValueError(name + " has other edits. No file was changed; report this message.")
    config_path = root/"config.json"
    cfg = json.loads(config_path.read_text(encoding="utf-8-sig"))
    if cfg.get("model") != "gpt-5.4-mini-2026-03-17":
        raise ValueError("This update targets the existing gpt-5.4-mini-2026-03-17 pilot configuration.")
    if cfg.get("extract_reasoning_effort") not in (None, "none", "low"):
        raise ValueError("Custom extract_reasoning_effort detected; no files changed.")
    cfg["extract_reasoning_effort"] = "low"
    updates = {root/name: source.encode("utf-8") for name,source in PATCH_FILES.items()}
    updates[config_path] = (json.dumps(cfg, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    if all(p.exists() and p.read_bytes() == data for p,data in updates.items()):
        print("ATOMIC_FIX_ALREADY_APPLIED")
        print("Next: py -3 atomic_tools.py check --out runs/atomic_check_v3 --max-requests 6 --max-usd 0.5")
        return
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    backup = root/"runs"/("atomic_fix_backup_" + stamp)
    originals = {p: p.read_bytes() if p.exists() else None for p in updates}
    for path,data in originals.items():
        if data is not None:
            target = backup/path.relative_to(root)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
    try:
        for path,data in updates.items():
            atomic_write(path,data)
    except BaseException:
        for path,data in originals.items():
            if data is None:
                path.unlink(missing_ok=True)
            else:
                atomic_write(path,data)
        raise
    print("ATOMIC_FIX_APPLIED")
    print("Backup:", backup)
    print("No API request was made. Historical run folders were preserved.")
    print("Next: py -3 -m unittest discover -s tests -v")
    print("Then: py -3 atomic_tools.py check --out runs/atomic_check_v3 --max-requests 6 --max-usd 0.5")
    print("Upload runs/atomic_check_v3/atomic_check.json for review before the revised pilot.")


